// Ghost Wallet's native core, as the app sees it.
//
// The bindings under src/ are generated by uniffi-bindgen-react-native from the
// Rust crate in core/ (`ubrn build ios --and-generate`) and exist only in a
// native build. The core generates, checks and saves account words; it keeps
// them in the Keychain, on this device only. JavaScript sees words only on the
// screens that show or take them: the new words on the backup screen, and the
// words the person types on the check and import screens. Nothing here logs
// them, and no error message carries them. The only other words this module
// passes over are the fixed public test words.
import {
  lookUpSavedAccountAtTip,
  type AccountAtTip,
  type FetchAccountState,
  type RestoreBindings,
  type SavedRestoreBindings,
} from './account-lookup';
import { TEST_WORDS } from './test-words';

export { TEST_WORDS_ACCOUNT_ZERO } from './test-words';
export type { AccountAtTip, FetchAccountState } from './account-lookup';

type GhostCoreBindings = RestoreBindings &
  SavedRestoreBindings & {
  accountZeroAddress(words: string): string;
  /** Generates 24 new words from the system's random source and holds them in native memory until saved or discarded. */
  newAccountWords(): string[];
  /** Whether the held new word at `position` (1 to 24) is `word`. */
  checkNewAccountWord(position: number, word: string): boolean;
  /**
   * Saves the held new words to the Keychain (this device only) and forgets them. Throws until
   * three different words have been checked right, and when an account is saved already.
   */
  saveNewAccount(): void;
  /** Forgets the held new words without saving them. */
  discardNewAccount(): void;
  /** Whether `word` is in the account word list. */
  isAccountWord(word: string): boolean;
  /** Checks 24 typed words (list and checksum) and saves them to the Keychain; throws when invalid. */
  importAccountWords(words: string): void;
  /** Whether account words are saved in the Keychain. */
  hasAccount(): boolean;
  /** Account 0 address of the saved words. */
  savedAccountZeroAddress(): string;
  /** The 24 words of the saved account, for the recovery words screen only. */
  savedAccountWords(): string[];
} & Partial<VanishBindings>;

/** The Vanish, Summon and Claim calls of core/src/vanish.rs, as generated. */
export type VanishBindings = {
  checkKeyWords(text: string): { verdict: string; position: number };
  prepareVanish(chainId: bigint, amountWei: string): CoreVanishCommit;
  takePhantomKeyWords(): string[];
  checkPhantomKeyWord(position: number, word: string): boolean;
  confirmPhantomKeySaved(): void;
  forgetPhantomKey(): void;
  signVanish(send: CoreVanishSend): CoreSigned;
  commitLeaf(commitData: ArrayBuffer, amountWei: string): CoinLeaf;
  revealLeaf(envelope: ArrayBuffer): { marker: ArrayBuffer; leaf: CoinLeaf };
  findKeyCoins(keyText: string, chainId: bigint, leaves: CoinLeaf[], spent: ArrayBuffer[]): KeyCoins;
  proveKeyReveal(keyText: string, request: CoreRevealRequest, leaves: CoinLeaf[], spent: ArrayBuffer[]): CoreProvedReveal;
  revealFeeWei(bRefWei: string): string;
  minVanishWei(bRefWei: string): string;
  feeWindow(tip: bigint): { referenceHeight: bigint; validUntil: bigint };
  commitEntryAddress(): string;
  vanishGasLimit(): bigint;
  testChainId(): bigint;
  transactionHash(signed: ArrayBuffer): ArrayBuffer;
  encodePaymentRecord(record: CorePaymentRecord): ArrayBuffer;
  decodePaymentRecord(bytes: ArrayBuffer): CorePaymentRecord;
  PaymentSequence: CorePaymentSequenceClass;
};

export type CoinLeaf = { commitment: ArrayBuffer; note: ArrayBuffer; salt?: ArrayBuffer };
export type KeyCoins = { status: string; amountWei: string };
export type CoreVanishCommit = { commitData: ArrayBuffer; amountWei: string; commitment: ArrayBuffer };
export type CoreVanishSend = {
  chainId: bigint;
  genesisHash: ArrayBuffer;
  nonce: bigint;
  commitData: ArrayBuffer;
  amountWei: string;
  maxPriorityFeePerGas: bigint;
  maxFeePerGas: bigint;
  gasLimit: bigint;
};
export type CoreSigned = { transactionHash: ArrayBuffer; sender: ArrayBuffer; envelope: ArrayBuffer };
export type CoreRevealRequest = {
  chainId: bigint;
  genesisHash: ArrayBuffer;
  recipient: ArrayBuffer;
  baseFeeRefWei: string;
  outWei?: string;
};
export type CoreProvedReveal = {
  transactionHash: ArrayBuffer;
  marker: ArrayBuffer;
  envelope: ArrayBuffer;
  feeWei: string;
  outWei: string;
  remainderWei: string;
  proveMillis: bigint;
};

/** The step sequence's identity, intent and record (core/src/step_sequence.rs). */
export type CoreIdentity =
  | { tag: 'AccountNonce'; inner: { account: ArrayBuffer; nonce: bigint } }
  | { tag: 'RevealMarker'; inner: { marker: ArrayBuffer } };
export type CorePaymentIntent = { kind: number | string; identity: CoreIdentity; details: ArrayBuffer };
export type CoreAttempt = { transactionHash: ArrayBuffer; validUntil?: bigint };
export type CorePaymentRecord = {
  id: string;
  intent: CorePaymentIntent;
  step: number | string;
  attempts: CoreAttempt[];
  inclusion?: { transactionHash: ArrayBuffer; blockHash: ArrayBuffer; blockHeight: bigint };
  version: number;
  checksum: ArrayBuffer;
};
export type CoreRecovery = { tag: string; inner?: { transactionHash?: ArrayBuffer; step?: number | string } };
export type CoreReceipt = { status: number | string; blockHash: ArrayBuffer; blockHeight: bigint };

export type CorePaymentStore = {
  save(record: CorePaymentRecord): void;
  load(id: string): CorePaymentRecord | undefined;
  list(): string[];
  remove(id: string): void;
  savePayload(id: string, transactionHash: ArrayBuffer, signedTransaction: ArrayBuffer): void;
  loadPayload(id: string, transactionHash: ArrayBuffer): ArrayBuffer | undefined;
};

export type CoreChainView = {
  receipt(transactionHash: ArrayBuffer): CoreReceipt | undefined;
  pending(transactionHash: ArrayBuffer): boolean;
  identityUsedBy(identity: CoreIdentity): ArrayBuffer | undefined;
  effectApplied(intent: CorePaymentIntent, transactionHash: ArrayBuffer): boolean;
  tipHeight(): bigint;
};

export type CorePaymentSequence = {
  record(): CorePaymentRecord;
  step(): number | string;
  recover(chain: CoreChainView): CoreRecovery;
  markBackedUp(): void;
  addAttempt(signedTransaction: ArrayBuffer, validUntil?: bigint): ArrayBuffer;
  markSent(): ArrayBuffer;
};

export type CorePaymentSequenceClass = {
  start(store: CorePaymentStore, id: string, intent: CorePaymentIntent): CorePaymentSequence;
  open(store: CorePaymentStore, id: string): CorePaymentSequence;
};

function bindings(): GhostCoreBindings {
  // Loaded lazily so that a missing native build fails here, not at import.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  return require('./src/index') as GhostCoreBindings;
}

/** Thrown when the core turns down words. Its message never holds the words. */
export class AccountWordsError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'AccountWordsError';
  }
}

/** Account 0 address (rescue-key scheme 0x0003) of the fixed test words. */
export function testWordsAccountZeroAddress(): string {
  return bindings().accountZeroAddress(TEST_WORDS);
}

export function newAccountWords(): string[] {
  return bindings().newAccountWords();
}

export function checkNewAccountWord(position: number, word: string): boolean {
  return bindings().checkNewAccountWord(position, word);
}

export function saveNewAccount(): void {
  bindings().saveNewAccount();
}

export function discardNewAccount(): void {
  try {
    bindings().discardNewAccount();
  } catch {
    // Nothing is held when the core is missing.
  }
}

export function isAccountWord(word: string): boolean {
  return bindings().isAccountWord(word);
}

export function importAccountWords(words: string): void {
  const core = bindings();
  try {
    core.importAccountWords(words);
  } catch {
    // The core's own error names no words, but drop it anyway so nothing
    // derived from the input travels further.
    throw new AccountWordsError('These 24 words are not a Ghost account.');
  }
}

/** Whether an account is saved; false when the core is missing. */
export function hasAccount(): boolean {
  try {
    return bindings().hasAccount();
  } catch {
    return false;
  }
}

export function savedAccountZeroAddress(): string {
  return bindings().savedAccountZeroAddress();
}

/**
 * Account `index` of the saved account at the node's tip, through the core's
 * current-state lookup; the words stay in native code. `fetchState` asks the
 * node for the address's balance and nonce at the tip's block hash.
 */
export function lookUpSavedAccount(
  index: number,
  tip: { height: number; hash: string },
  fetchState: FetchAccountState,
): Promise<AccountAtTip> {
  return lookUpSavedAccountAtTip(bindings(), index, tip, fetchState);
}

/**
 * The saved account's 24 recovery words, for the recovery words screen only
 * (after Face ID or the passcode). Throws when no account can be read.
 */
export function savedAccountWords(): string[] {
  return bindings().savedAccountWords();
}

/** The Vanish, Summon and Claim calls; throws when this build has no native core. */
export function vanishCore(): VanishBindings {
  const core = bindings();
  if (typeof core.checkKeyWords !== 'function' || typeof core.prepareVanish !== 'function') {
    throw new Error('this build has no Vanish in its native core');
  }
  return core as GhostCoreBindings & VanishBindings;
}

/**
 * What typed words are: a Phantom Key, a wallet's recovery words, or why
 * neither. The core never echoes the words back.
 */
export function checkKeyWords(text: string): { verdict: string; position: number } {
  const check = bindings().checkKeyWords;
  if (typeof check !== 'function') {
    throw new Error('this build cannot check keys');
  }
  return check(text);
}
